        amx:DS0039 ;
    amlo:isIndicatedBy amx:IND02910,
        amx:IND02942,
        amx:IND02943,
        amx:IND02944,
        amx:IND02945,
        amx:IND02946 ;
    amlo:shortDescription "Adversaries typically recruit unsuspecting or complicit individuals (money mules) to channel illicit proceeds through personal accounts, obscuring the true source and beneficiaries of the funds."@en ;
    amlo:stixId "attack-pattern--066129c2-169b-477f-9cf6-e2bb410a44e0" .

